import math, sys

b = 1 + math.sqrt(2)
inv_a = 2 - math.sqrt(2)

def search(K):
    M = int(math.floor(K / b))
    bx = [0]*(M+1)
    for x in range(1, M+1):
        bx[x] = int(math.floor(b*x))
    w = [0]*(K+1)
    s = [0]*(K+1)
    count = [0]
    maxdisc = [0.0]
    def feasible(t):
        for x in range(1, M+1):
            if bx[x] <= t:
                e = s[x] + s[bx[x]] - 2*x
                if e < -1 or e > 1:
                    return False
        for x in range(1, M+1):
            if bx[x] > t and x <= t:
                lo_t = 2*x - 1 - s[x]
                hi_t = 2*x + 1 - s[x]
                lo = s[t]; hi = s[t] + (bx[x]-t)
                if hi < lo_t or lo > hi_t:
                    return False
        return True
    sys.setrecursionlimit(100000)
    def rec(t):
        if t > K:
            count[0] += 1
            # discrepancy at endpoints plus running sup
            mxd = 0.0
            for x in range(1, K+1):
                d = abs(s[x] - inv_a*x)
                if d > mxd: mxd = d
            if mxd > maxdisc[0]: maxdisc[0] = mxd
            return
        for v in (0,1):
            w[t]=v; s[t]=s[t-1]+v
            if feasible(t):
                rec(t+1)
        s[t]=s[t-1]
    rec(1)
    return count[0], maxdisc[0]

