                if hi < lo_t or lo > hi_t:
                    return False
        return True
    sys.setrecursionlimit(100000)
    def rec(t):
        nonlocal best
        if t > K:
            mxd = max(abs(s[x]-inv_a*x) for x in range(1,K+1))
